<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!collector_marketplace_ready())redirect('upgrade-collector-marketplace.php');$p=collector_profile_by_user((int)user()['id']);app_header('My Collector Marketplace');?><section class="dashboard-hero"><p class="eyebrow">COLLECTOR DASHBOARD</p><h1>My Collection</h1><p>Manage your listings, offers, favorites, and public collector profile.</p></section><?php if(!$p):?><section class="empty-state"><h2>No collector profile yet</h2><p><a class="button primary" href="create.php">Open Collector Profile</a></p></section><?php else:$stats=db()->prepare("SELECT COUNT(*) total,SUM(status='active') active,SUM(status='sold') sold,SUM(status='traded') traded FROM collector_items WHERE collector_id=?");$stats->execute([$p['id']]);$st=$stats->fetch();?><section class="dev-stat-grid"><article class="app-card dev-stat"><span>Total items</span><strong><?=(int)$st['total']?></strong></article><article class="app-card dev-stat"><span>Active</span><strong><?=(int)$st['active']?></strong></article><article class="app-card dev-stat"><span>Sold</span><strong><?=(int)$st['sold']?></strong></article><article class="app-card dev-stat"><span>Traded</span><strong><?=(int)$st['traded']?></strong></article></section><section class="app-card"><h2><?=e($p['shop_name'])?></h2><p><span class="badge"><?=e(ucfirst($p['status']))?></span></p><p><a class="button primary" href="manage.php?id=<?=$p['id']?>">Manage Marketplace</a> <a class="button ghost" href="view.php?slug=<?=urlencode($p['slug'])?>">View Public Profile</a></p></section><?php endif;app_footer();
